  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Deoxygedunin, the closest structural analogue (Morgan 0.3444) sharing the furan-lactone and acetate motif, produced brain TrkB phosphorylation after i.p. dosing in mice, directly demonstrating that this limonoid scaffold can access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Bufotalin, a related steroid-like natural product with a furanone/lactone, achieved brain concentrations significantly higher than blood after i.v. administration in mice, supporting CNS access for this lipophilic polycyclic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Bufalin distributed primarily to brain after i.v. delivery in mice with prolonged brain retention, further supporting that these polycyclic furan/lactone natural products cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Brusatol, a more polar quassinoid, was not detected in brain; however, its multiple hydroxyls and different substitution pattern make it a weaker transfer model than the lipophilic furan-lactone analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query is a lipophilic furan-lactone limonoid closely related to deoxygedunin, which has direct in vivo evidence of brain penetration; related bufadienolides also show brain uptake. The negative brusatol record is less transferable due to higher polarity.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux transporter liability not directly assessed for the query.",
    "Morgan similarities are moderate (0.21–0.34), so structural transfer is not exact."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

